vec3 vector_normalize(vec3 v) {
    float length = sqrtf(v.x*v.x + v.y*v.y + v.z*v.z);
    return (vec3){v.x/length, v.y/length, v.z/length};
}

ray ray_create(vec3 origin, vec3 direction) {
    return (ray){origin, direction};
}

vec3 ray_at(ray r, float t) {
    return (vec3){r.origin.x + t*r.direction.x, ...};
}

int sphere_intersect(ray r, sphere s, hit_record *out) {
    vec3 oc = {r.origin.x - s.center.x, ...};
    float a = vector_dot(r.direction, r.direction);
    float b = 2.0 * vector_dot(oc, r.direction);
    float c = vector_dot(oc, oc) - s.radius*s.radius;
    float discriminant = b*b - 4*a*c;
    if (discriminant < 0) return 0;
    float sqrt_disc = sqrt(discriminant);
    float t = (-b - sqrt_disc) / (2*a);
    ...
}

vec3 plane_intersect(ray r, plane p, hit_record *out) {
    float t = (p.distance - vector_dot(r.origin, p.normal)) / vector_dot(r.direction, p.normal);
    if (t <= 0) return 0;
    ...
}

vec3 sky_color(ray r) {
    vec3 unit = vector_normalize(r.direction);
    float t = 0.5 * (unit.y + 1.0);
    return (1.0-t)*white + t*blue;
}

bool is_in_shadow(vec3 p, vec3 light_dir) {
    ray r = ray_create(p, light_dir);
    hit_record rec;
    return sphere_intersect(r, sphere, &rec) && rec.t > 0.001;
